// Package pg is the PostgreSQL control-plane store: configuration, identity
// and alert state. Queries are generated by sqlc from queries/*.sql into the
// sqlc subpackage; this package owns connection setup and migrations.
package pg

import (
	"context"
	"embed"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/the-real-rajp/monitor/internal/store/migrate"
	"github.com/the-real-rajp/monitor/internal/store/pg/sqlc"
)

//go:embed migrations/*.sql
var migrationFS embed.FS

// DB wraps a connection pool and the generated query set.
type DB struct {
	Pool *pgxpool.Pool
	Q    *sqlc.Queries
}

// Open connects to PostgreSQL and verifies the connection.
func Open(ctx context.Context, url string) (*DB, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("parse postgres url: %w", err)
	}
	cfg.MaxConnLifetime = time.Hour
	cfg.HealthCheckPeriod = 30 * time.Second
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("connect postgres: %w", err)
	}
	pingCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping postgres: %w", err)
	}
	return &DB{Pool: pool, Q: sqlc.New(pool)}, nil
}

// Close releases the pool.
func (d *DB) Close() { d.Pool.Close() }

// Ping reports whether the database is reachable.
func (d *DB) Ping(ctx context.Context) error { return d.Pool.Ping(ctx) }

// Migrate applies pending schema migrations.
func (d *DB) Migrate(ctx context.Context, log *slog.Logger) (int, error) {
	ms, err := migrate.Load(migrationFS, "migrations")
	if err != nil {
		return 0, err
	}
	return migrate.Run(ctx, log.With("store", "postgres"), target{d.Pool}, ms)
}

// WithTx runs fn inside a transaction using a query set bound to it.
func (d *DB) WithTx(ctx context.Context, fn func(q *sqlc.Queries) error) error {
	tx, err := d.Pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(d.Q.WithTx(tx)); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

type target struct{ pool *pgxpool.Pool }

func (t target) EnsureTable(ctx context.Context) error {
	_, err := t.pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		version    integer PRIMARY KEY,
		name       text NOT NULL,
		applied_at timestamptz NOT NULL DEFAULT now()
	)`)
	return err
}

func (t target) Applied(ctx context.Context) ([]int, error) {
	rows, err := t.pool.Query(ctx, `SELECT version FROM schema_migrations`)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rows, pgx.RowTo[int])
}

func (t target) Apply(ctx context.Context, m migrate.Migration) error {
	tx, err := t.pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	// Serialise concurrent migrators (several server replicas starting at once).
	if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock(7342001)`); err != nil {
		return err
	}
	var exists bool
	if err := tx.QueryRow(ctx, `SELECT EXISTS (SELECT 1 FROM schema_migrations WHERE version = $1)`, m.Version).Scan(&exists); err != nil {
		return err
	}
	if exists {
		return nil // another replica applied it while we waited on the lock
	}
	if _, err := tx.Exec(ctx, m.SQL); err != nil {
		return err
	}
	if _, err := tx.Exec(ctx, `INSERT INTO schema_migrations (version, name) VALUES ($1, $2)`, m.Version, m.Name); err != nil {
		return err
	}
	return tx.Commit(ctx)
}
